mapper.select:
SELECT user_id FROM aid_notification_recipient
WHERE notification_id=#{notificationId}
ORDER BY user_id

SELECT u.user_id,u.user_name,u.nick_name,u.avatar,u.status,u.create_time FROM sys_user u WHERE u.del_flag='0' AND EXISTS (SELECT 1 FROM sys_user_role ur WHERE ur.user_id=u.user_id AND ur.role_id=2) AND NOT EXISTS (SELECT 1 FROM sys_user_role ur WHERE ur.user_id=u.user_id AND ur.role_id<>2)
AND (u.user_name LIKE CONCAT('%',#{keyword},'%') OR u.nick_name LIKE CONCAT('%',#{keyword},'%'))
ORDER BY u.create_time DESC,u.user_id DESC LIMIT #{offset},#{limit}

SELECT id,title,summary,message_type,recipient_type,recipient_count,status,scheduled_time,publish_time, publish_seq,version,creator_id,creator_name,updater_id,updater_name,create_time,update_time FROM aid_system_notification WHERE 1=1 AND status=#{status}
AND (title LIKE CONCAT('%',#{keyword},'%') OR summary LIKE CONCAT('%',#{keyword},'%'))
ORDER BY (publish_time IS NULL),publish_time DESC,publish_seq DESC, COALESCE(scheduled_time,update_time) DESC,id DESC LIMIT #{offset},#{limit}

mapper.update:
UPDATE aid_system_notification
SET status='WITHDRAWN',updater_id=#{updaterId},updater_name=#{updaterName},update_time=#{updateTime},version=version+1
WHERE id=#{id} AND status='PUBLISHED' AND version=#{expectedVersion}

mapper.select:
SELECT id FROM aid_system_notification
WHERE status='SCHEDULED' AND scheduled_time<=#{now}
ORDER BY scheduled_time,id
LIMIT #{limit}

mapper.update:
UPDATE aid_notification_operation
SET notification_id=#{notificationId},response_version=#{responseVersion},complete_time=#{completeTime}
WHERE id=#{operationId} AND complete_time IS NULL
